<?php
namespace Nakhostin\PerformanceEngine\CSS;
final class CriticalCSSGenerator { private const MAX_BYTES = 50000; public function generate( string $css, CSSManifest $usage, string $page_signature, array $components = array() ): CriticalCSSManifest { $data = $usage->to_array(); $required = array_fill_keys( array_merge( (array) ( $data['used'] ?? array() ), array( 'html', 'body', ':root' ) ), true ); $critical = ''; if ( preg_match_all( '/([^{}]+)\{([^{}]*)\}/', $css, $matches, PREG_SET_ORDER ) ) { foreach ( $matches as $rule ) { $selectors = array_map( 'trim', explode( ',', trim( $rule[1] ) ) ); if ( array_intersect_key( array_fill_keys( $selectors, true ), $required ) ) { $candidate = trim( $rule[1] ) . '{' . trim( $rule[2] ) . '}'; if ( strlen( $critical . $candidate ) > self::MAX_BYTES ) { break; } $critical .= $candidate; } } } return new CriticalCSSManifest( array( 'manifest_version' => 1, 'page_signature' => sanitize_key( $page_signature ), 'generated_at' => time(), 'css' => $critical, 'components' => array_values( array_map( 'strval', $components ) ) ) ); } }
